CREATE TABLE staff_import_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, batch_id BIGINT UNSIGNED NOT NULL, source_row INT UNSIGNED NOT NULL, data_json TEXT NOT NULL, result VARCHAR(500) NOT NULL, staff_identity_id BIGINT UNSIGNED NULL, FOREIGN KEY(batch_id) REFERENCES staff_import_batches(id), FOREIGN KEY(staff_identity_id) REFERENCES staff_identities(id), UNIQUE(batch_id,source_row)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
